package net.civeira.phylax.feature.observe.observedslo.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSlo;
import net.civeira.phylax.feature.observe.observedslo.domain.valueobject.RouteVO;

class RouteValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of route of observed slo")
  void test_route_value_holder_assign_plain_value() {
    Object holder = new Object();
    RouteValueHolder<Object> value = new RouteValueHolder<>(holder);
    Assertions.assertSame(holder, value.route("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getRouteValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getRoute().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.routeNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getRouteValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getRoute().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of route of observed slo")
  void test_route_value_holder_assign_value_object() {
    Object holder = new Object();
    RouteValueHolder<Object> value = new RouteValueHolder<>(holder);
    RouteVO vo = RouteVO.from("one");
    Assertions.assertFalse(value.getRouteValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.route(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRouteValue().orElseThrow());
    Assertions.assertSame(holder, value.route(Optional.empty()));
    Assertions.assertFalse(value.getRouteValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.route(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRouteValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of route of observed slo against the original")
  void test_route_value_holder_read() {
    Object holder = new Object();
    RouteValueHolder<Object> value = new RouteValueHolder<>(holder);
    RouteVO vo = RouteVO.from("one");
    RouteVO other = RouteVO.from("one");
    ObservedSlo original = Mockito.mock(ObservedSlo.class);
    Mockito.when(original.getRouteValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRoute(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readRoute(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.route(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRoute(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRoute(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of route of observed slo")
  void test_route_value_holder_unset() {
    Object holder = new Object();
    RouteValueHolder<Object> value = new RouteValueHolder<>(holder);
    RouteVO vo = RouteVO.from("one");
    value.route(vo);
    Assertions.assertSame(holder, value.unsetRouteIfMatches("route_other"));
    Assertions.assertTrue(value.getRouteValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRouteIfMatches("route"));
    Assertions.assertFalse(value.getRouteValue().isPresent(),
        "The field name must clear the value");
    value.route(vo);
    Assertions.assertSame(holder, value.unsetRoute());
    Assertions.assertFalse(value.getRouteValue().isPresent(), "Unset must clear the value");
  }
}
